export const filmTocCss=`
.book-page[data-generated=index]{background-color:#171717}.book-page[data-generated=index] .book-content,.book-page[data-generated=index] .book-content :is(h1,h2,h3,h4,h5,p,strong){color:#fff}.book-page[data-generated=index] .book-number{color:#fff!important}.book-page[data-generated=toc]{padding:20mm;color:#fff;background-color:#0b0b17}.book-page[data-generated=toc] .book-content{height:257mm;text-align:left;font-family:"Courier Prime",monospace;font-weight:700;color:#fff}
.book-page[data-generated=toc]::before{content:"";position:absolute;inset:18.245mm 12.845mm;background:rgba(0,0,0,.5);border:1pt solid #000;pointer-events:none;z-index:0}.book-page[data-generated=toc] .book-content{position:relative;z-index:1}.book-page[data-generated=toc] .book-number{z-index:1}
.book-page[data-generated=toc] h2{font-size:16pt!important;font-variant:normal;text-transform:none!important;color:#fff;margin:0 0 5pt;text-align:center}
.book-page[data-generated=toc] .book-content p{display:flex;align-items:baseline;gap:2mm;font-family:"Courier Prime",monospace;font-weight:700;color:#fff;font-size:11pt;line-height:1.2;margin:0 0 5pt}
.book-page[data-generated=toc] p::after{content:"";order:1;flex:1;min-width:4mm;border-bottom:1px dotted currentColor}
.book-page[data-generated=toc] [data-toc-number]{order:2;white-space:nowrap}.book-page[data-generated=toc] [data-toc-label]{max-width:90%;overflow-wrap:anywhere}
.book-page[data-generated=toc] .book-content p[data-toc-level="2"]{font-size:10pt;margin-left:4.233mm}.book-page[data-generated=toc] .book-content p[data-toc-level="3"]{font-size:8pt;margin-left:8.467mm}.book-page[data-generated=toc] .book-content p[data-toc-level="4"]{font-size:8pt;margin-left:12.7mm}.book-page[data-generated=toc] .book-content p[data-toc-level="5"]{font-size:8pt;margin-left:16.933mm}
.book-page[data-generated=toc] .book-number{font-family:"Courier Prime",monospace;font-size:16pt;font-weight:700;color:#fff}`;

export const filmTocWordStyles=`<w:style w:type="paragraph" w:styleId="FilmTocHeading"><w:name w:val="Sommaire"/><w:pPr><w:jc w:val="center"/><w:spacing w:after="100"/></w:pPr><w:rPr><w:rFonts w:ascii="Courier Prime" w:hAnsi="Courier Prime"/><w:b/><w:color w:val="FFFFFF"/><w:sz w:val="32"/></w:rPr></w:style>${[1,2,3,4,5].map(level=>`<w:style w:type="paragraph" w:styleId="FilmToc${level}"><w:name w:val="toc ${level}"/><w:pPr><w:jc w:val="left"/><w:tabs><w:tab w:val="right" w:leader="dot" w:pos="9628"/></w:tabs><w:spacing w:after="100"/><w:ind w:left="${(level-1)*240}"/></w:pPr><w:rPr><w:rFonts w:ascii="Courier Prime" w:hAnsi="Courier Prime"/><w:b/><w:color w:val="FFFFFF"/><w:sz w:val="${level===1?22:level===2?20:16}"/></w:rPr></w:style>`).join('')}`;
